@startuml

class Hospital {
}

class Office {
}

class User {
}

class Doctor extends User {
}

class Patient extends User {
  + Email : string
}

class Schedule {
  + Date : date
  + StartTime : time
  + EndTime : time
}

class Appointment {
  + AppointmentType : string
}

enum AppointmentType {
  Blood_Test
  Consultation
  Surgery
}

Hospital "1" *-- "1..*" Office
Doctor "1..*" -- "1..*" Office : applies to
Doctor "1" -- "0..*" Schedule : creates
Office "1" -- "0..*" Schedule : has
Patient "1" -- "0..*" Appointment : books
Doctor "1" -- "0..*" Appointment : has
Schedule "1" -- "0..1" Appointment : is for

@enduml

